    r.currency,
    r.description,
    r.description_i18n,
    r.export_port,
    r.id,
    r.incoterm,
    r.incoterm_place,
    r.lead_time_days,
    r.monthly_capacity,
    r.moq,
    r.name,
    r.name_i18n,
