-- ---------------------------------------------------------------------------
-- 5. ẢNH ĐẠI DIỆN VÀ HẠN CHIA SẺ GIÁ
-- ---------------------------------------------------------------------------
update public.supplier_products p
set featured_media_id = m.id
from public.media_assets m
where m.product_id = p.id
  and m.kind = 'image'
  and p.id = any(array['beb6a0a0-69b0-5051-b0ff-8b9e5bcf6000'::uuid, 'da717eeb-d786-5fd0-af48-4a5b26c6951d'::uuid, '71dcac73-6e03-5bbe-9581-66e3d81c4082'::uuid, '3808bf71-3bb6-55fc-a099-f456752dd825'::uuid, 'da6267c3-e15b-54e3-94a5-5f649c82e571'::uuid, 'fab96629-4034-59a9-a493-4f7e06885df5'::uuid, '840e6daa-2594-5be9-bfe0-e151f7b78efe'::uuid, 'b7d6be9d-8aef-55bd-be26-a8fad36d48aa'::uuid, '0fdc3b87-28b6-5b7f-bc6f-b6d63c26657a'::uuid, '8496d97b-4c00-5941-bb4c-132cb3d6d42f'::uuid, 'eb0e2e64-95f2-5b2b-b02c-bf7169ad0371'::uuid, 'cc3767e7-19ea-5693-89b5-b7e9c0cd4426'::uuid, '36803b7a-55e3-5ba3-a767-04b9d4ae1213'::uuid, '490e13cb-f47a-52f6-be80-efaec9c14aa6'::uuid, 'f7ac2fe9-cdcd-5d4c-b16a-2cb5235f9a65'::uuid, 'cd4fa624-fcba-5fc5-aeb1-84dd8f67c015'::uuid, '85a1dac6-c374-5d8c-af95-10da0ca62525'::uuid, 'd6bad558-204f-513c-8451-9987b22e8fe7'::uuid, '5cf02e4f-6e12-5992-8995-d9240101a021'::uuid, '87f91bed-67a3-59a0-8d07-388d73714f30'::uuid, '8acc96db-560b-57d3-9cb1-acff680cde84'::uuid, '259f7a0f-2b31-5115-83c1-bcae977cc9be'::uuid, '604673e1-0846-5048-a7a0-fa9c0af4bdab'::uuid, '72b22ece-1c9d-5708-af30-be1895e420b6'::uuid, 'aea049a0-99ce-5783-afa1-ca00661e0d42'::uuid, '30cacb66-400f-5de0-8b33-749fd05150d9'::uuid, 'bca65316-7181-5374-8fa2-5becc53ddb6b'::uuid])
