-- ---------------------------------------------------------------------------
-- KIỂM TRA SAU KHI CHẠY
-- ---------------------------------------------------------------------------
select
  (select count(*) from public.suppliers where status = 'published')        as published_suppliers,
  (select count(*) from public.supplier_products where ready_for_buyer)     as ready_products,
  (select count(*) from public.media_assets
     where storage_path like 'products/staging/%%')                         as staging_images,
  (select count(distinct spr.category) from public.supplier_products spr)    as categories_with_products;

